/**
 * Tutor Amma — Cloudflare Worker entry.
 *
 *  /rt/livehub    -> LiveHub Durable Object   (home-visit safety tracking)
 *  /rt/classroom  -> ClassroomHub Durable Object (live digital classroom)
 *  everything else -> the Next.js app built by OpenNext
 *
 * On the first request of a fresh deployment the D1 schema is created
 * automatically (idempotent), so a new database works without a manual
 * migration step.
 */
// @ts-ignore — generated by `opennextjs-cloudflare build`
import { default as nextHandler } from "../.open-next/worker.js";
import { MiniIO } from "./mini-io";
import { attachLiveHub } from "./livehub";
import { attachClassroomHub } from "./classroomhub";
import { SCHEMA_SQL } from "./schema";

interface Env {
  DB: D1Database;
  AI: unknown;
  LIVEHUB: DurableObjectNamespace;
  CLASSROOMHUB: DurableObjectNamespace;
  WORKER_SELF_REFERENCE: Fetcher;
  INTERNAL_SECRET?: string;
  [k: string]: unknown;
}

let schemaReady: Promise<void> | null = null;

const EXPECTED_TABLES = (SCHEMA_SQL.match(/CREATE TABLE IF NOT EXISTS/g) || []).length;

/** Creates any missing tables/indexes. Idempotent, so it also applies additive schema upgrades. */
async function ensureSchema(db: D1Database) {
  const row = await db
    .prepare("SELECT count(*) AS c FROM sqlite_master WHERE type='table' AND name NOT LIKE '\\_%' ESCAPE '\\' AND name NOT LIKE 'sqlite_%' AND name <> 'd1_migrations'")
    .first<{ c: number }>();
  if ((row?.c ?? 0) >= EXPECTED_TABLES) return;
  const statements = SCHEMA_SQL.split(/;\s*\n/)
    .map((s) => s.replace(/^\s*--.*$/gm, "").trim())
    .filter(Boolean);
  await db.batch(statements.map((s) => db.prepare(s)));
}

const SECURITY_HEADERS: Record<string, string> = {
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "X-Frame-Options": "SAMEORIGIN",
  "Permissions-Policy": "camera=(self), microphone=(self), geolocation=(self), display-capture=(self)",
};

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/rt/livehub" || url.pathname === "/rt/classroom") {
      const ns = url.pathname === "/rt/livehub" ? env.LIVEHUB : env.CLASSROOMHUB;
      const stub = ns.get(ns.idFromName("global"));
      return stub.fetch(request);
    }

    if (env.DB && url.pathname.startsWith("/api/")) {
      if (!schemaReady) schemaReady = ensureSchema(env.DB).catch((e) => {
        schemaReady = null;
        throw e;
      });
      try {
        await schemaReady;
      } catch (e) {
        return Response.json({ error: { code: "DB_UNAVAILABLE", message: "Database is not ready: " + (e as Error).message } }, { status: 503 });
      }
    }

    const res: Response = await nextHandler.fetch(request, env, ctx);
    if (res.status === 101 || res.webSocket) return res;
    const out = new Response(res.body, res);
    for (const [k, v] of Object.entries(SECURITY_HEADERS)) if (!out.headers.has(k)) out.headers.set(k, v);
    return out;
  },
};

/* ---------------- Durable Objects ---------------- */

export class LiveHubDO {
  private io = new MiniIO();
  constructor(_state: DurableObjectState, env: Env) {
    const appFetch = (path: string, init?: RequestInit) =>
      env.WORKER_SELF_REFERENCE.fetch(new Request(new URL(path, "https://tutor-amma.internal"), init));
    attachLiveHub(this.io, appFetch, env.INTERNAL_SECRET || "amma-livehub-2026");
  }
  fetch(request: Request) {
    return this.io.upgrade(request);
  }
}

export class ClassroomHubDO {
  private io = new MiniIO();
  constructor(_state: DurableObjectState, _env: Env) {
    attachClassroomHub(this.io);
  }
  fetch(request: Request) {
    return this.io.upgrade(request);
  }
}

// @ts-ignore — OpenNext helper Durable Objects (unused unless enabled in open-next.config.ts)
export { DOQueueHandler, DOShardedTagCache } from "../.open-next/worker.js";
